    ('TR', 4, 19, 3, lambda dr,dc:(dr,-dc)),
    ('BL', 21, 5, 1, lambda dr,dc:(-dr,dc)),
    ('BR', 19, 18, 4, lambda dr,dc:(-dr,-dc)),
