                if 0 <= rr < 27 and 0 <= cc < 27:
                    if out_grid[rr][cc] not in (4,color):
                        print('COLLISION', name, rr,cc,out_grid[rr][cc],color)
                    out_grid[rr][cc]=color
                    written.append((name,color,rr,cc))
